-- ==========================================================================
-- B4 FOLLOW-ON FIX (rotating): rotating: duplicate question rewritten into a new question
--
-- Courses: rotating. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/rotating.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql rotating. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- rotating intermediate module m06-the-professional-reading ord 7
  select case when md5(prompt) = 'd05c397926fdb7c68f57501265887a5d' and md5(coalesce(explanation, '')) = 'feaa77cb2a41f0a305cc9144fcecfe49' and md5(options::text) = md5('["On suction, on power and on the fluid.", "On change, on the fluid and on the count of machines.", "On suction, on change and on the region the duty lands in.", "On suction, on change and on the fluid."]'::jsonb::text) and answer_index = 3 then 'old'
              when md5(prompt) = 'a64e13f886b5d0c39496826e8afe2424' and md5(coalesce(explanation, '')) = 'bbb48f6d4346edc6fb456ad0e5b5427a' and md5(options::text) = md5('["Neither is an input: both are solved from the duty flow.", "The stage count is an input the user types, and the machine count is solved from the system curve crossing.", "Both are inputs, but the stage count is capped by the 300 degF default discharge limit before the train is run.", "The machine count is an input, and the stage count is an answer out of two limits at once."]'::jsonb::text) and answer_index = 3 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'rotating' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-the-professional-reading' and ord = 7 and active;
  if v_state is null then raise exception 'B4 fix rotating refused: no row for rotating intermediate module m06-the-professional-reading ord 7'; end if;
  if v_state = 'other' then raise exception 'B4 fix rotating refused: rotating intermediate module m06-the-professional-reading ord 7 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'A pump station''s machine count and a compressor''s stage count are both whole numbers. How does the onward lesson say they differ?', options = '["Neither is an input: both are solved from the duty flow.", "The stage count is an input the user types, and the machine count is solved from the system curve crossing.", "Both are inputs, but the stage count is capped by the 300 degF default discharge limit before the train is run.", "The machine count is an input, and the stage count is an answer out of two limits at once."]'::jsonb,
           answer_index = 3, explanation = 'Everything in this tier had a curve to work with, and the machine count was typed in. A compressor''s stage count is discovered from two limits at once, the engine names which one governed, and the stages then chain into a train with a real cooling duty between them.'
     where app_slug = 'rotating' and tier = 'intermediate' and scope = 'module' and module_key is not distinct from 'm06-the-professional-reading' and ord = 7 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix rotating refused: rotating intermediate module m06-the-professional-reading ord 7 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'rotating' and active;
  if v_total <> 396 then raise exception 'B4 fix rotating refused: rotating holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix rotating: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
